_BLOCK = 4096
# Leaner large-list launches move twice the data per program.
_BLOCK_BIG = 8192
_GRID_CAP = 65535
_MAX_SLOTS = 16
_MAX_DIMS = 8
_INT32_LIMIT = 1 << 31
# Above this many elements the device stream dominates the per-entry host cost,
# so lean per-entry launches win over one wide fused launch.
_FUSE_NUMEL = 50_000_000

_LAUNCH_CACHE = {}


@triton.jit
def _tile(s_ptr, a_ptr, b_ptr, off, n, value, EXACT: tl.constexpr):
    if EXACT:
        x = tl.load(s_ptr + off)
        av = tl.load(a_ptr + off)
        bv = tl.load(b_ptr + off)
        r = x.to(tl.float32) + value * av.to(tl.float32) * bv.to(tl.float32)
        tl.store(s_ptr + off, r.to(s_ptr.dtype.element_ty))
    else:
        m = off < n
        x = tl.load(s_ptr + off, mask=m, other=0.0)
        av = tl.load(a_ptr + off, mask=m, other=0.0)
        bv = tl.load(b_ptr + off, mask=m, other=0.0)
        r = x.to(tl.float32) + value * av.to(tl.float32) * bv.to(tl.float32)
        tl.store(s_ptr + off, r.to(s_ptr.dtype.element_ty), mask=m)


