def _direct_launch(jit_fn, tag, vals, tensors, ptrs, nl, exact, grid):
    """Launch a compiled kernel directly, reusing the bound kernel per signature.

    `vals` holds every declared parameter in declaration order (runtime args
    followed by the two constexpr values) and `ptrs` the matching data pointers
    already read by the caller.  The cache key covers everything the compiled
    binary depends on: the constexpr values, the argument dtypes, the exact int
    values and the pointer alignment classes Triton specializes on.
    """
    if not _DIRECT_OK:
        return False
    dev = _driver.active.get_current_device()
    key = (
        dev,
        tag,
        exact,
        tuple(nl),
        tuple(t.dtype for t in tensors),
        tuple(p & 15 for p in ptrs),
    )
    ck = _LAUNCH_CACHE.get(key)
    if ck is None:
        try:
            ck = jit_fn.warmup(*vals[:-2], EXACT=vals[-2], BLOCK=vals[-1], grid=grid)
        except Exception:
            return False
        _LAUNCH_CACHE[key] = ck
    stream = _driver.active.get_current_stream(dev)
    md = ck.launch_metadata(grid, stream, *vals)
    ck.foreach_addcmul_scalar_(
        grid[0],
        1,
        1,
        stream,
        ck.function,
        ck.packed_metadata,
        md,
        _knobs.runtime.launch_enter_hook,
        _knobs.runtime.launch_exit_hook,
        *vals,
    )
    return True


def _launch_group(tensors, nl, ptrs, value):
    """Fuse up to _MAX_SLOTS (contiguous, shape-matched) entries into one launch."""
    k = len(nl)
    total = 0
    exact = True
    for x in nl:
        total += (x + _BLOCK - 1) // _BLOCK
        if x % _BLOCK:
            exact = False
    if total == 0:
        return
    if k < _MAX_SLOTS:
        pad = _MAX_SLOTS - k
        tensors = tensors + tensors[-3:] * pad
        ptrs = ptrs + ptrs[-3:] * pad
        nl = nl + [0] * pad
    grid = (total if total < _GRID_CAP else _GRID_CAP,)
    vals = tensors + nl + [value, exact, _BLOCK]
    if _direct_launch(_fused16, "f", vals, tensors, ptrs, nl, exact, grid):
        return
    _fused16[grid](*tensors, *nl, value, EXACT=exact, BLOCK=_BLOCK)


def _launch_group4(tensors, nl, ptrs, value):
    """Fuse up to 4 (contiguous, shape-matched) entries into one lean launch."""
    k = len(nl)
    total = 0
    exact = True
    for x in nl:
        total += (x + _BLOCK_BIG - 1) // _BLOCK_BIG
        if x % _BLOCK_BIG:
            exact = False
    if total == 0:
        return
    if k < 4:
        pad = 4 - k
        tensors = tensors + tensors[-3:] * pad
        ptrs = ptrs + ptrs[-3:] * pad
        nl = nl + [0] * pad
    grid = (total if total < _GRID_CAP else _GRID_CAP,)
    vals = tensors + nl + [value, exact, _BLOCK_BIG]
    if _direct_launch(_fused4, "4", vals, tensors, ptrs, nl, exact, grid):
        return
    _fused4[grid](*tensors, *nl, value, EXACT=exact, BLOCK=_BLOCK_BIG)


def _launch_one(s, a, b, value):
    nelem = s.numel()
    total = (nelem + _BLOCK - 1) // _BLOCK
    exact = nelem % _BLOCK == 0
    grid = (total if total < _GRID_CAP else _GRID_CAP,)
    tensors = [s, a, b]
    nl = [nelem]
    ptrs = [s.data_ptr(), a.data_ptr(), b.data_ptr()]
    vals = tensors + nl + [value, exact, _BLOCK]
    if _direct_launch(_addcmul_flat, "1", vals, tensors, ptrs, nl, exact, grid):
        return
    _addcmul_flat[grid](s, a, b, nelem, value, EXACT=exact, BLOCK=_BLOCK)


def _bcast_dims_strides(t, shape):
    """Right-aligned broadcast of t to `shape`; returns (dims, strides)."""
    ts = list(t.shape)
    st = list(t.stride())
    pad = len(shape) - len(ts)
    dims = [1] * pad + ts
    strides = [0] * pad + st
    out_dims = []
    out_strides = []
    for i in range(len(shape)):
        d = dims[i]
        s = shape[i]
        if d == s:
            out_dims.append(d)
            out_strides.append(strides[i])
        elif d == 1:
            out_dims.append(s)
            out_strides.append(0)
        else:
            raise ValueError("shape mismatch is not broadcastable in _foreach_addcmul_")
    return out_dims, out_strides


def _run_strided(s, a, b, value):
    nelem = s.numel()
    shape = s.shape
    sd, ss = _bcast_dims_strides(s, shape)
    ad, as_ = _bcast_dims_strides(a, shape)
    _, bs = _bcast_dims_strides(b, shape)

    # collapse adjacent dimensions that are contiguous for all three operands
    dims = []
    sst = []
    ast = []
    bst = []
    for i in range(len(shape)):
        if dims:
            j = len(dims) - 1
            nxt = shape[i]
            if (
                sst[j] == ss[i] * nxt
                and ast[j] == as_[i] * nxt
                and bst[j] == bs[i] * nxt
            ):
                dims[j] *= nxt
                continue
        dims.append(shape[i])
        sst.append(ss[i])
        ast.append(as_[i])
        bst.append(bs[i])

    if len(dims) > _MAX_DIMS:
        raise ValueError("unsupported tensor rank for _foreach_addcmul_")

    pad = _MAX_DIMS - len(dims)
    dims = [1] * pad + dims
    sst = [0] * pad + sst
    ast = [0] * pad + ast
    bst = [0] * pad + bst

    total = (nelem + _BLOCK - 1) // _BLOCK
    grid = (total if total < _GRID_CAP else _GRID_CAP,)
    _addcmul_strided[grid](
        s,
        a,
        b,
        nelem,
        total,
        value,
        dims[0],
        dims[1],
        dims[2],
        dims[3],
        dims[4],
        dims[5],
        dims[6],
        dims[7],
        sst[0],
        sst[1],
        sst[2],
        sst[3],
        sst[4],
        sst[5],
        sst[6],
        sst[7],
        ast[0],
        ast[1],
        ast[2],
        ast[3],
        ast[4],
        ast[5],
        ast[6],
        ast[7],
        bst[0],
        bst[1],
        bst[2],
        bst[3],
        bst[4],
        bst[5],
        bst[6],
        bst[7],
        BLOCK=_BLOCK,
    )


def foreach_addcmul_scalar_(self, tensor1, tensor2, value=1):
    n = len(self)
    if n == 0:
        return None
    if torch.is_tensor(value):
        value = value.item()
    else:
        value = float(value)
    if len(tensor1) != n or len(tensor2) != n:
        raise ValueError("_foreach_addcmul_ expects tensor lists of equal length")

    # One pass: validate the dense/equal-shape form ATen's sequential per-entry
    # semantics allow us to batch, and collect pointers/numels for the launch.
    fast = True
    total_numel = 0
    nl = []
    tensors = []
    ptrs = []
    seen = {}
    for s, a, b in zip(self, tensor1, tensor2):
        if not (
            s.is_contiguous()
            and a.is_contiguous()
            and b.is_contiguous()
            and s.shape == a.shape
            and s.shape == b.shape
        ):
            fast = False
            break
        nelem = s.numel()
        if nelem >= _INT32_LIMIT:
            fast = False
            break
        p = s.data_ptr()
        if p in seen:
            # ATen applies list entries in order; two slots on one storage
            # would race inside a single fused launch.
            fast = False
            break
        seen[p] = 1
        total_numel += nelem
        nl.append(nelem)
        tensors.append(s)
        tensors.append(a)
        tensors.append(b)
        ptrs.append(p)
        ptrs.append(a.data_ptr())
        ptrs.append(b.data_ptr())

    if fast:
        if total_numel == 0:
            return None
        if total_numel > _FUSE_NUMEL:
            # Device-bound: fusing a few entries per launch removes most of the
            # per-launch device drain without the register pressure of 16 slots.
            for start in range(0, n, 4):
                stop = min(start + 4, n)
                _launch_group4(
                    tensors[3 * start : 3 * stop],
                    nl[start:stop],
                    ptrs[3 * start : 3 * stop],
                    value,
                )
            return None
        if n <= _MAX_SLOTS:
            _launch_group(tensors, nl, ptrs, value)
            return None
        for start in range(0, n, _MAX_SLOTS):
            stop = min(start + _MAX_SLOTS, n)
            _launch_group(
                tensors[3 * start : 3 * stop],
                nl[start:stop],
                ptrs[3 * start : 3 * stop],
                value,
            )
        return None

    for i in range(n):
        s = self[i]
        if s.numel() == 0:
            continue
        a = tensor1[i]
        b = tensor2[i]
        if (
            s.is_contiguous()
            and a.is_contiguous()
            and b.is_contiguous()
            and s.shape == a.shape
            and s.shape == b.shape
        ):
            _launch_one(s, a, b, value)
        else:
            _run_strided(s, a, b, value)
    return None
